CREATE OR REPLACE PROCEDURE sp(para_President_Vote NUMBER, para_Class_President_Vote NUMBER, para_Treasurer_Vote NUMBER, para_city_code VARCHAR2) IS
 v_next_stuid NUMBER;
 CURSOR ref_cursor1 IS SELECT * FROM "Voting_record" WHERE "Treasurer_Vote" < para_Treasurer_Vote AND ("President_Vote" <> "Vice_President_Vote" OR "Secretary_Vote" <> "Treasurer_Vote") FOR UPDATE;
 CURSOR ref_cursor2 IS SELECT * FROM "Student" FOR UPDATE;
 rec1 ref_cursor1%ROWTYPE;
 rec2 ref_cursor2%ROWTYPE;
BEGIN
 SELECT NVL(MAX("StuID"), 0) + 1 INTO v_next_stuid FROM "Voting_record";
 INSERT INTO "Voting_record" ("StuID", "President_Vote", "Class_President_Vote") VALUES (v_next_stuid, para_President_Vote, para_Class_President_Vote);
 UPDATE "Student" SET {SLOT_1} = {SLOT_2} WHERE {SLOT_3};
 IF {SLOT_4} THEN
   UPDATE "Student" SET {SLOT_5} = {SLOT_6}
   WHERE {SLOT_7};
   OPEN ref_cursor1;
   LOOP
     FETCH ref_cursor1 INTO rec1;
     EXIT WHEN ref_cursor1%NOTFOUND;
     DELETE FROM "Voting_record" WHERE CURRENT OF ref_cursor1;
   END LOOP;
   CLOSE ref_cursor1;
   UPDATE "Student" stu
   SET {SLOT_8} = {SLOT_9}
   WHERE {SLOT_10};
 ELSE
   OPEN ref_cursor2;
   LOOP
     FETCH ref_cursor2 INTO rec2;
     EXIT WHEN ref_cursor2%NOTFOUND;
     UPDATE "Student" SET {SLOT_11} = {SLOT_12} WHERE CURRENT OF ref_cursor2;
   END LOOP;
   CLOSE ref_cursor2;
 END IF;
END;

## Slots

### {SLOT_1}
Kind: target

What: The column being set is the Cairnwick turn target.

### {SLOT_3}
Kind: predicate

What: Match the student whose student ID is the generated student ID, per ordinary SQL UPDATE semantics.

### {SLOT_4}
Kind: condition

What: The first argument equals the second argument. This decides which branch of the IF runs.

### {SLOT_5}
Kind: target

What: The column being set is the student's city code.

### {SLOT_6}
Kind: value

What: The value to put there is the Cairnwick turn value.

### {SLOT_7}
Kind: predicate

What: Match students whose ID appears in at least one voting record where the record's treasurer vote is strictly less than the third argument and, for that same record, either its president vote differs from its vice-president vote or its secretary vote differs from its treasurer vote. The deletion in the same branch must not destroy the evidence that identifies these students.

### {SLOT_8}
Kind: target

What: The column being set is the student's city code.

### {SLOT_9}
Kind: value

What: The value to put there is the fourth argument (the city-code value passed in).

### {SLOT_10}
Kind: predicate

What: Match students for which no voting record has the same student ID as that student. That includes students with no voting record at all and students whose only voting records were just deleted.

### {SLOT_12}
Kind: value

What: The value to put there is the Cairnwick turn value.

### Note

For {SLOT_8}, the column being set is the student's student ID.

